const HANDOFF_USAGE =
  'Optional handoff flags on every command: --caller-agent claude|codex|cursor|grokbot, --caller-model <model>, --caller-session <id>, or --handoff <json>. Human-direct invocations omit them.';
const VARIANT_LOOKUP_TELEMETRY_TIMEOUT_MS = 100;

export const splitMcpServeArgs = (rest: string[]): string[] | null => {
  const serveIndex = rest.indexOf('serve');
  if (serveIndex === -1) {
    return null;
  }
  return [...rest.slice(0, serveIndex), ...rest.slice(serveIndex + 1)];
};

const flagValue = (args: string[], flag: string): string | undefined => {
  const index = args.indexOf(flag);
  if (index >= 0) return args[index + 1];
  const prefix = `${flag}=`;
  return args.find((arg) => arg.startsWith(prefix))?.slice(prefix.length);
};

const CALLER_AGENT_BY_EDITOR: Record<string, string> = {
  cursor: 'cursor',
  claude: 'claude',
  'claude-desktop': 'claude',
  codex: 'codex',
};

export const mcpServeArgsFromStaleRegistration = (rest: string[]): string[] => {
  const args: string[] = [];
  let editor: string | undefined;
  for (let index = 0; index < rest.length; index += 1) {
    const arg = rest[index];
    if (arg === '--editor') {
      editor = rest[index + 1];
      index += 1;
      continue;
    }
    if (arg.startsWith('--editor=')) {
      editor = arg.slice('--editor='.length);
      continue;
    }
    args.push(arg);
  }
  const callerAgent = editor
    ? CALLER_AGENT_BY_EDITOR[editor.trim().toLowerCase()]
    : undefined;
  if (callerAgent && !args.includes('--caller-agent')) {
    args.push('--caller-agent', callerAgent);
  }
  return args;
};

export const dispatch = async (
  command: string,
  rest: string[],
  io: CliIO,
  options: { signal?: AbortSignal } = {},
): Promise<CliCommandResult> => {
  if (command === 'mcp') {
    const serveArgs = splitMcpServeArgs(rest);
    if (serveArgs) {
      const { handleMcpServe } = await import('./commands/mcpServe');
      return handleMcpServe(serveArgs, io);
    }
    const { ensureLoginShellPath } = await import('../utils/loginShellPath');
    ensureLoginShellPath();
    const { cleanupRemovedMcpRegistrations } =
      await import('../install/legacyMcp');
    const cleanup = cleanupRemovedMcpRegistrations({
      editor: flagValue(rest, '--editor'),
    });
    const cleanupGuidance = cleanup.changed
      ? `Removed the deleted Rivet MCP registration for ${cleanup.targets.join(', ')}. Restart the editor to stop its current restart loop, then run \`npx -y rivet-design@latest install\` to refresh the full agent setup.`
      : 'Run `npx -y rivet-design@latest install` to update your agent setup (this also removes stale MCP registrations).';
    io.writeProgress(
      'The Rivet MCP server has been removed. Agents drive Rivet with `rivet` CLI commands now.\n' +
        cleanupGuidance,
    );
    if (!process.stdin.isTTY) {
      const { handleMcpServe } = await import('./commands/mcpServe');
      return handleMcpServe(mcpServeArgsFromStaleRegistration(rest), io);
    }
    return errorResult(
      'mcp',
      'MCP_REMOVED',
      `The Rivet MCP server has been removed. ${cleanupGuidance} Then drive Rivet with \`rivet\` CLI commands (\`rivet open\`, \`rivet variants start\`, …).`,
      {
        registrationCleanup: {
          changed: cleanup.changed,
          targets: cleanup.targets,
        },
      },
    );
  }
  if (command === 'open') {
    const { handleLibraryOpen } = await import('./commands/libraryOpen');
    return withReferenceOnboarding(await handleLibraryOpen(rest, io));
  }
  if (command === 'stop') {
    const { handleStop } = await import('./commands/stop');
    return handleStop(rest);
  }
  if (command === 'status') {
    const { handleStatus } = await import('./commands/status');
    return handleStatus(rest, io);
  }
  if (command === 'update') {
    const { handleUpdate } = await import('./commands/update');
    return handleUpdate(rest);
  }
  if (command === 'version') {
    const { handleVersion } = await import('./commands/version');
    return handleVersion(rest);
  }
  if (command === 'wait') {
    const { handleWait } = await import('./commands/wait');
    return handleWait(rest);
  }
  if (command === 'variants') {
    const { handleVariants } = await import('./commands/variants');
    return withReferenceOnboarding(await handleVariants(rest, { io }));
  }
  if (command === 'profile') {
    const { handleProfile } = await import('./commands/profile');
    return handleProfile(rest);
  }
  if (command === 'context') {
    const { handleContext } = await import('./commands/context');
    return handleContext(rest, options);
  }
  if (command === 'evidence') {
    if (rest[0] !== 'capture') {
      return errorResult(
        'evidence',
        'USAGE_ERROR',
        'Usage: rivet evidence capture --url <url>',
      );
    }
    const { handleEvidenceCapture } = await import('./commands/evidence');
    return handleEvidenceCapture(rest.slice(1));
  }
  if (command === 'reference') {
    if (rest[0] !== 'fetch') {
      return errorResult(
        'reference',
        'USAGE_ERROR',
        'Usage: rivet reference fetch <url>',
      );
    }
    const { handleReferenceFetch } = await import('./commands/reference');
    return withReferenceOnboarding(await handleReferenceFetch(rest.slice(1)));
  }
  if (command === 'auth') {
    const { handleAuth } = await import('./commands/auth');
    return handleAuth(rest);
  }
  if (command === '__hub') {
    const { startHubServer } = await import('../library/HubServer');
    const { TelemetryService } = await import('../services/TelemetryService');
    const telemetry = new TelemetryService({
      enabled: process.env.RIVET_LIBRARY_TELEMETRY !== '0',
      source: 'core',
    });
    const hub = await startHubServer({
      telemetry,
      isSourceSyncAllowed: !rest.includes('--no-source-sync'),
    });
    if (hub) {
      const shutdown = () => {
        void hub
          .close()
          .then(() => telemetry.shutdown())
          .then(() => process.exit(0));
      };
      process.once('SIGTERM', shutdown);
      process.once('SIGINT', shutdown);
      await new Promise<void>((resolve) => process.once('beforeExit', resolve));
    }
    await telemetry.shutdown();
    return {
      envelope: {
        schemaVersion: CLI_SCHEMA_VERSION,
        ok: true,
        command: '__hub',
        data: {},
      },
      exitCode: 0,
    };
  }
  if (command === '__serve') {
    const { handleServe } = await import('./commands/serve');
    return handleServe(rest, io);
  }
  return errorResult(command, 'USAGE_ERROR', `Unknown command: ${command}`);
};

const stdoutReservedForProtocolIO = (io: CliIO): CliIO => ({
  ...io,
  writeEnvelope: (envelope) => io.writeProgress(serializeEnvelope(envelope)),
});

export const runCliControlCommand = async (
  args: string[],
  io: CliIO = processCliIO,
): Promise<number> => {
  const { redirectLogsToStderr } = await import('../utils/logger');
  redirectLogsToStderr();

  const [command, ...rest] = args;
  if (rest.includes('--no-telemetry'))
    process.env.RIVET_TELEMETRY_DISABLED = '1';
  const startedAt = Date.now();

  if (rest.includes('--help') || rest.includes('-h')) {
    const usage = COMMAND_USAGE[command] ?? [];
    return emitResult(io, {
      envelope: {
        schemaVersion: CLI_SCHEMA_VERSION,
        ok: true,
        command,
        data: { usage, handoff: HANDOFF_USAGE },
      },
      exitCode: 0,
    });
  }

  let result: CliCommandResult;
  try {
    result = await dispatch(command, rest, io);
  } catch (error) {
    result = commandErrorResult(command, error);
  }

  const exitCode = emitResult(
    command === 'mcp' ? stdoutReservedForProtocolIO(io) : io,
    result,
  );

  if (
    !rest.includes('--no-telemetry') &&
    !(command === '__hub' && process.env.RIVET_LIBRARY_TELEMETRY === '0')
  ) {
    try {
      const { TelemetryService } = await import('../services/TelemetryService');
      const telemetry = new TelemetryService({ source: 'cli' });
      telemetry.trackCliCommandCompleted({
        command: result.envelope.command,
        ok: result.envelope.ok,
        exitCode,
        errorCode: result.envelope.ok ? undefined : result.envelope.error.code,
        isRecoverable: result.envelope.ok
          ? undefined
          : result.envelope.error.isRecoverable,
        serverUnavailableReason: serverUnavailableReasonForEnvelope(
          result.envelope,
        ),
        durationMs: Date.now() - startedAt,
        designContextKind: designContextKindForEnvelope(result.envelope),
        ...variantContextMetadataForArgs(command, rest),
        ...browserMetadataForEnvelope(result.envelope),
        ...verificationMetadataForEnvelope(result.envelope),
        ...callerTelemetryFieldsFromArgs(rest),
        error: result.cause,
      });
      telemetry.reportInstallRefActivations();
      await telemetry.shutdown(
        result.envelope.command === 'variants.get'
          ? VARIANT_LOOKUP_TELEMETRY_TIMEOUT_MS
          : undefined,
      );
    } catch {}
  }

  return exitCode;
};
